 void EnsureOverviewK(DesktopWindow w){if(w.ColumnsJ.Count>0){foreach(var c in new[]{new TableColumnJ{Id="velocity",Label="Velocity",Width=80,Visible=false},new TableColumnJ{Id="radial",Label="Radial",Width=80,Visible=false},new TableColumnJ{Id="transversal",Label="Transversal",Width=90,Visible=false},new TableColumnJ{Id="angular",Label="Angular",Width=90,Visible=false}})if(!w.ColumnsJ.Any(existing=>existing.Id==c.Id))w.ColumnsJ.Add(c);}if(w.TabsK.Count==0){w.TabsK=OverviewTabK.Defaults();w.TabK=Math.Max(0,w.TabsK.FindIndex(t=>t.Name==w.PresetJ));}w.TabK=Math.Clamp(w.TabK,0,w.TabsK.Count-1);}
 IEnumerable<SpaceRow> AllOverviewRowsK(){var local=world.Targets.Where(t=>t.Alive).Select(t=>new SpaceRow(t.Id,t.Name,t.DroneId.Length>0?"Drone":t.Kind.ToString(),Vector3.Distance(t.Position,world.Player.Position),t.Velocity.Length(),t.Kind,true));var ids=world.Targets.Select(t=>t.Id).ToHashSet();var remote=world.Celestials.Where(c=>c.Id!=world.SolarCelestial&&!ids.Contains(c.Id)).Select(c=>new SpaceRow(c.Id,c.Name,c.Kind.ToString(),(c.Anchor-world.SystemPosition).Length,0,null,false));return local.Concat(remote).Concat(world.Bookmarks.Where(b=>b.System==world.SystemId).Select(b=>new SpaceRow(b.Id,b.Name,"Bookmark",(b.Position-world.SystemPosition).Length,0,null,false)));}
 bool OverviewAllowsK(OverviewTabK tab,SpaceRow row){var t=world.Targets.FirstOrDefault(t=>t.Id==row.Id);return tab.Allows(row.Type,t?.Friendly==true,t?.Kind==TargetKind.Raider&&t.Friendly==false,world.RetainedLocks.Any(l=>l.Id==row.Id)||world.LockedId==row.Id,world.SelectedId==row.Id);}
 OverviewTabK? BracketFilterK(){var w=desktop.FirstOrDefault(w=>w.Owner==bracketOwnerK&&w.Kind==ViewMode.OverviewJ)??desktop.LastOrDefault(w=>w.Kind==ViewMode.OverviewJ);if(w==null)return null;EnsureOverviewK(w);var tab=w.TabsK[w.TabK];return tab.Brackets=="All"?new(){Exceptions=[]}:tab.Brackets=="None"?new(){Types=["__none__"],Exceptions=[]}:tab.Brackets=="Same as tab"?tab:w.TabsK.FirstOrDefault(t=>t.Name==tab.Brackets)??tab;}
 bool ShowBracketK(SpaceTarget target){var tab=BracketFilterK();return tab==null||tab.Allows(target.DroneId.Length>0?"Drone":target.Kind.ToString(),target.Friendly,target.Kind==TargetKind.Raider&&!target.Friendly,world.LockedId==target.Id||world.RetainedLocks.Any(l=>l.Id==target.Id),world.SelectedId==target.Id);}
 bool ShowBracketK(Celestial c){var tab=BracketFilterK();return tab==null||tab.Allows(c.Kind.ToString(),false,false,false,world.SelectedId==c.Id);}
 void OpenOverviewSettingsK(DesktopWindow target){EnsureOverviewK(target);EnsureWindow(ViewMode.OverviewSettingsK);desktop.Last(w=>w.Kind==ViewMode.OverviewSettingsK).InfoKey=target.Owner;}
 void OverviewMenuK(DesktopWindow w){EnsureOverviewK(w);var tab=w.TabsK[w.TabK];ShowPopup("Overview / "+tab.Name,[("Overview settings",()=>OpenOverviewSettingsK(w)),("Move tab to new window",()=>{var n=NewInstanceJ(ViewMode.OverviewJ);n.TabsK=[tab.Copy()];n.TabK=0;n.PresetJ=tab.Name;n.ColumnsJ=w.ColumnsJ.Select(c=>new TableColumnJ{Id=c.Id,Label=c.Label,Width=c.Width,Visible=c.Visible}).ToList();if(w.TabsK.Count>1){w.TabsK.RemoveAt(w.TabK);w.TabK=0;}SaveDesktop();}),("Use this window for space brackets",()=>{bracketOwnerK=w.Owner;SaveDesktop();}),("Add tab",()=>{if(w.TabsK.Count<20){w.TabsK.Add(new(){Name="Tab "+(w.TabsK.Count+1),Exceptions=[]});w.TabK=w.TabsK.Count-1;SaveDesktop();}else world.Say("Maximum 20 overview tabs.");}),("Duplicate tab",()=>{if(w.TabsK.Count<20){var copy=tab.Copy();copy.Name+=" copy";w.TabsK.Add(copy);w.TabK=w.TabsK.Count-1;SaveDesktop();}}),("Export overview",()=>{var path=Path.Combine(Path.GetDirectoryName(DemoWorld.SavePath)!,"overview-k.json");File.WriteAllText(path,JsonSerializer.Serialize(w,new JsonSerializerOptions{WriteIndented=true}));world.Say("Overview exported to "+path);}),("Import overview",()=>ImportOverviewK(w))]);}
 void ImportOverviewK(DesktopWindow w){try{var path=Path.Combine(Path.GetDirectoryName(DemoWorld.SavePath)!,"overview-k.json");var incoming=JsonSerializer.Deserialize<DesktopWindow>(File.ReadAllText(path))??throw new InvalidDataException("Empty overview");if(incoming.TabsK.Count is <1 or >20||incoming.TabsK.Any(t=>t.Name.Length is <1 or >40||t.Types==null||t.Exceptions==null)||incoming.ColumnsJ.Count>20||incoming.ColumnsJ.Any(c=>c.Width is <40 or >600))throw new InvalidDataException("Invalid overview profile");w.TabsK=incoming.TabsK;w.ColumnsJ=incoming.ColumnsJ;w.TabK=0;SaveDesktop();}catch(Exception e){world.Say("Overview import refused: "+e.Message);}}
 double OverviewValueK(SpaceRow row,string key){var target=world.Targets.FirstOrDefault(t=>t.Id==row.Id);var relative=(target?.Velocity??Vector3.Zero)-world.Player.Velocity;var delta=(target?.Position??world.Player.Position)-world.Player.Position;double radial=delta.LengthSquared()>.01?Vector3.Dot(relative,Vector3.Normalize(delta)):0;double transverse=Math.Sqrt(Math.Max(0,relative.LengthSquared()-radial*radial));return key switch{"velocity"=>row.Velocity,"radial"=>radial,"transversal"=>transverse,"angular"=>transverse/Math.Max(1,row.Distance),_=>row.Distance};}
 void DrawOverviewK(DesktopWindow w){EnsureOverviewK(w);if(w.ColumnsJ.Count==0)w.ColumnsJ=[new(){Id="name",Label="Name",Width=150},new(){Id="distance",Label="Distance",Width=90},new(){Id="type",Label="Type",Width=110},new(){Id="velocity",Label="Velocity",Width=80,Visible=false},new(){Id="radial",Label="Radial",Width=80,Visible=false},new(){Id="transversal",Label="Transversal",Width=90,Visible=false},new(){Id="angular",Label="Angular",Width=90,Visible=false}];int x=w.X+8,y=w.Y+38;int tabWidth=100,columns=Math.Max(1,(w.Width-45)/tabWidth);for(int i=0;i<w.TabsK.Count;i++){int tab=i;ui.Button(new(x+i%columns*tabWidth,y+i/columns*28,tabWidth-4,24),ShortInfo(w.TabsK[i].Name,13),()=>{w.TabK=tab;w.PresetJ=w.TabsK[tab].Name;w.ScrollJ=0;bracketOwnerK=w.Owner;SaveDesktop();},"Overview tab / "+w.TabsK[i].Name,w.TabK==i);}ui.Button(new(w.Bounds.Right-35,y,26,24),"+",()=>OverviewMenuK(w),"Overview / tab actions");y+=((w.TabsK.Count+columns-1)/columns)*28;SearchFieldJ(w,new(x,y,w.Width-16,28),"Filter overview...");y+=35;int cx=x,header=w.Compact?24:30;foreach(var col in w.ColumnsJ.Where(c=>c.Visible)){var c=col;var rect=new Rectangle(cx,y,c.Width,header);ui.Button(rect,c.Label+(w.SortJ==c.Id?(w.DescendingJ?" v":" ^"):""),()=>{if(w.SortJ==c.Id)w.DescendingJ=!w.DescendingJ;else{w.SortJ=c.Id;w.DescendingJ=false;}SaveDesktop();},"Column / "+c.Id);ui.Hits.Add(new(new(rect.Right-4,rect.Y,4,rect.Height),()=>{resizeColumnJ=c;resizeColumnOwnerJ=w;columnOriginJ=mouse.X;columnWidthJ=c.Width;},"Resize column / "+c.Id));cx+=c.Width;}y+=header+2;var rows=AllOverviewRowsK().Where(r=>OverviewAllowsK(w.TabsK[w.TabK],r)&&r.Name.Contains(w.QueryJ,StringComparison.OrdinalIgnoreCase));rows=w.SortJ is "name"?rows.OrderBy(r=>r.Name):w.SortJ=="type"?rows.OrderBy(r=>r.Type):rows.OrderBy(r=>OverviewValueK(r,w.SortJ));if(w.DescendingJ)rows=rows.Reverse();var array=rows.ToArray();int height=w.Compact?24:30,visible=Math.Max(1,(w.Bounds.Bottom-y-33)/height);w.ScrollJ=Math.Clamp(w.ScrollJ,0,Math.Max(0,array.Length-visible));foreach(var row in array.Skip(w.ScrollJ).Take(visible)){var r=row;var target=world.Targets.FirstOrDefault(t=>t.Id==r.Id);Color c=target?.Friendly==true?Green:r.Kind==TargetKind.Raider?Red:White;ui.Box(new(x,y,w.Width-26,height-1),world.SelectedId==r.Id?new Color(40,65,77):new Color(19,29,35));int tx=x;foreach(var col in w.ColumnsJ.Where(c=>c.Visible)){string value=col.Id switch{"name"=>r.Name,"type"=>r.Type,"distance"=>SolarCatalog.Distance(r.Distance),"angular"=>OverviewValueK(r,col.Id).ToString("0.0000")+" rad/s",_=>OverviewValueK(r,col.Id).ToString("0")+" m/s"};ui.Text(ShortInfo(value,Math.Max(4,col.Width/7)),tx+5,y+6,c,12);tx+=col.Width;}ui.Hits.Add(new(new(x,y,w.Width-26,height-1),()=>world.SelectedId=r.Id,"J entity / "+r.Id));y+=height;}DrawScrollbarJ(w,new(w.Bounds.Right-14,w.Y+140,8,Math.Max(20,y-w.Y-140)),array.Length,visible);ui.Text(array.Length+" objects / "+w.TabsK[w.TabK].Name,x,w.Bounds.Bottom-25,Muted,11);}
 void DrawOverviewSettingsK(DesktopWindow settings){var w=desktop.FirstOrDefault(w=>w.Owner==settings.InfoKey&&w.Kind==ViewMode.OverviewJ);if(w==null){ui.Text("Open an overview, then choose Overview settings.",settings.X+18,settings.Y+55,Muted,14);return;}EnsureOverviewK(w);var tab=w.TabsK[w.TabK];int x=settings.X+16,y=settings.Y+44,width=settings.Width-32;ui.Text("Tab / "+tab.Name,x,y,Cyan,16);FieldK(new(x,y+28,width-185,30),tab.Name,v=>{if(v.Length is >0 and <=40){tab.Name=v;w.PresetJ=v;}},"Overview settings / tab name");ui.Button(new(x+width-173,y+28,173,30),"Save",SaveDesktop);y+=80;ui.Text("TYPE FILTERS",x,y,Cyan,12);y+=26;string[] types=["Raider","Asteroid","Container","Wreck","Drone","Station","Stargate","Wormhole","Planet","Moon","Sun","AsteroidBelt","IceField","GasCloud","Bookmark"];for(int i=0;i<types.Length;i++){string type=types[i];ui.Button(new(x+i%4*190,y+i/4*30,183,26),(tab.Types.Contains(type)?"[x] ":"[ ] ")+type,()=>{if(!tab.Types.Remove(type))tab.Types.Add(type);SaveDesktop();},"Overview type / "+type,tab.Types.Contains(type));}y+=132;ui.Text("EXCEPTIONS / FIRST MATCH WINS",x,y,Cyan,12);y+=26;foreach(var rule in tab.Exceptions.ToArray()){string r=rule;int idx=tab.Exceptions.IndexOf(rule);ui.Button(new(x,y,width-155,27),rule,()=>{tab.Exceptions[idx]=r.EndsWith(":show")?r.Replace(":show",":hide"):r.Replace(":hide",":show");SaveDesktop();});ui.Button(new(x+width-145,y,65,27),"Up",()=>{if(idx>0){tab.Exceptions.RemoveAt(idx);tab.Exceptions.Insert(idx-1,r);SaveDesktop();}});ui.Button(new(x+width-72,y,65,27),"Remove",()=>{tab.Exceptions.Remove(r);SaveDesktop();});y+=31;}ui.Button(new(x,y,180,27),"Add exception",()=>ShowPopup("Exception",new[]{"friendly","hostile","locked","selected"}.Select(state=>(state,(Action)(()=>{tab.Exceptions.Add(state+":show");SaveDesktop();})))));y+=43;ui.Button(new(x,y,width,30),"Bracket filter: "+tab.Brackets,()=>ShowPopup("Space brackets",new[]{"Same as tab","All","None"}.Concat(w.TabsK.Select(t=>t.Name)).Distinct().Select(name=>(name,(Action)(()=>{tab.Brackets=name;bracketOwnerK=w.Owner;SaveDesktop();})))));ui.Text("No checked types means all types. Exceptions override type filters.",x,settings.Bounds.Bottom-30,Muted,12);}
